    label: "Fill Icon",
    type: "toggle",
    applicableTo: ["bpmnStartEvent", "bpmnEndEvent", "bpmnIntermediateEvent", "bpmnExclusiveGateway", "bpmnParallelGateway", "bpmnInclusiveGateway", "bpmnEventGateway", "bpmnTask", "bpmnSubProcess", "bpmnCallActivity"],
